        rem = Integral % 2

        # Append 0 in binary 
        binary += str(rem); 

        Integral //= 2

    # Reverse string to get original
    # binary equivalent 
    binary = binary[ : : -1] 

    # Append point before conversion 
    # of fractional part 
    binary += '.'

    # Conversion of fractional part
    # to binary equivalent 
