    <?php
// PHP program to convert fractional decimal
// to binary number

// Function to convert decimal to binary upto
// k-precision after decimal point
function decimalToBinary($num, $k_prec)
{
    $binary = "";

    // Fetch the integral part of decimal number
    $Integral = (int)($num);

    // Fetch the fractional part decimal number
    $fractional = $num - $Integral;

    // Conversion of integral part to
    // binary equivalent
    while ($Integral)
    {
        $rem = $Integral % 2;

        // Append 0 in binary
        $binary.=chr($rem + 48 );

        $Integral = (int)($Integral/2);
    }

    // Reverse string to get original binary
    // equivalent
    $binary=strrev($binary);

    // Append point before conversion of
    // fractional part
    $binary.='.';

    // Conversion of fractional part to
    // binary equivalent
    while ($k_prec--)
    {
        // Find next bit in fraction
        $fractional *= 2;
        $fract_bit = (int)$fractional;

        if ($fract_bit == 1)
        {
            $fractional -= $fract_bit;
            $binary.=chr(1 + 48 );
        }
        else
            $binary.=chr(0 + 48 );
    }

    return $binary;
}

// Driver code

